//! How a letter typed without its mark is written, for every part of speech.
//! Each rule reads the letter before it, the letter, the letters after it and,
//! after the word's end, the part of speech (`#` is the word's start or end):
//! the longest one that matches decides (`tatio#` → `ā`, as in `-ātiō`; `#de`
//! → `ē`, as in `dē-`; `ae` → `e`, a diphthong; `eni#numeral` → `ē`, as in
//! `quīngēnī`), giving each way of writing the letter with how many of the
//! dictionary's letters in that place are written so.

